-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["220af383b60d9222"] = { "Ma per rispondere a queste domande occorre condurre altri studi ed esperimenti sul pendente, e temo che il Lordamere Interment Camp non possa mettere a disposizione né gli uomini né l'attrezzatura necessari. Così ho inviato il pendente di sanguinite a Dalaran tramite un corriere, con istruzioni precise su come esaminarlo, affinché possano evitare le frustrazioni che ho avuto io.", "." },
  ["225dd37063ed40ed"] = { "Per questa spedizione ho riunito Ajeck Rouack e Sir S. J Erlgadin, insieme al mio fidato servitore, Barnil Stonepot. Ho combattuto al fianco del padre di Ajeck in molte battaglie in difesa dell'⟦Alliance=Alleanza⟧. Vederla ormai adulta è davvero speciale. Suo padre l'ha istruita bene nell'uso delle armi. La sua abilità con l'arco mi fa chiedere se nelle sue vene non scorra sangue elfico.", "." },
  ["22ac9901db7788a2"] = { "Scrivo questo messaggio con gli inchiostri più potenti che riesco a creare, {name}. Maledirebbe all'istante chiunque osasse leggerlo all'infuori di te. Tanto è grande il mio potere. Evoco demoni dalla ⟦Twisting Nether=Distorsione Fatua⟧ a mio piacimento. Tormento i miei nemici nel sonno e sul campo di battaglia. E ora anche tu hai visto il potere della mia via. I miei fratelli ne sono compiaciuti.\n\nCercami nelle profondità dell'Antro del Tirocinio, quando avrai imparato a orientarti. Vorrei parlarti di questioni importanti.\n\n-Nartok, istruttore degli stregoni", "." },
  ["22cbd1719323b4c4"] = { "--Giorno 17\nUleg è tornato dalla sua missione. Ha fallito, e Thargil è stato catturato. Ho mandato Uleg a consegnare questo rapporto a Nazeer.\n\nIo resterò qui. Ho notato un aumento del traffico navale al largo della costa di Theramore. Continuerò la sorveglianza e riferirò di persona ogni evento degno di nota.", "." },
  ["22dd9cc0b18cd88c"] = { "JARIEN E SOTHOS, continua...\n\nFu così che si trovarono ad affrontare le prove richieste a chi aspira a unirsi alla Crociata. In particolare ambivano a un posto da cavaliere tra i ranghi, che a quanto pare richiedeva prove più difficili. Si scoprì infatti in seguito che Sothos aveva fallito la prova finale. Jarien però non volle accettarlo e, in aperta sfida, pretese che gli fosse permesso di unirsi a lei tra i cavalieri. Da quanto abbiamo saputo, il Gran Crociato Dathrohan li uccise entrambi sul posto, nel mezzo delle sue stanze.\n\nEcco perché un altro di questi luoghi infestati è il Crimson Throne, all'interno dello Scarlet Bastion di Stratholme.", "." },
  ["22df0d19bb53a01b"] = { "Se non riesco a trovare la gemma nascosta nel santuario, potrebbe averla uno dei murloc.\n\nL'asta\nQuesta parte della verga fu affidata ai treant vicino a quello che oggi si chiama ⟦Felwood=Vilbosco⟧. Né i mezzorsi né la mia gente avrebbero potuto sospettare che creature tanto magnifiche potessero un giorno cadere preda della corruzione che ha travolto la terra.\n\nLe mie ricerche mi dicono che i guardiani custodivano il pezzo in una piccola radura, chiuso in uno scrigno. Per scoprire di più, dovrò parlare con Shael'dryn.", "." },
})
